            // maybe they returned a CREATE result - check if it ran\n                return {\n                    passed: false,\n                    feedback: 'La tabla \"pagos\" no aparece. Verifica la sintaxis del CREATE TABLE y haz SELECT sobre sqlite_master.'\n                };\n            }\n            return {\n                passed: true,\n                feedback: '✅ Tabla \"pagos\" creada correctamente en el esquema.'\n            };\n        }\n    },\n    {\n        id: 9,\n        slug: \"insertar-datos\",\n        title: \"Poblar la tabla\",\n        subtitle: \"DML: INSERT INTO\",\n        unitId: 3,\n        difficulty: 2,\n        xpReward: 110,\n        estimatedTime: \"12 min\",\n        context: '\\uD83D\\uDDC4️ El Tesorero: \"Una tabla vac\\xeda no sirve de nada. Inserta al menos 3 pagos de alumnos reales.\"',\n        objective: \"Inserta **3 o m\\xe1s registros** en la tabla `pagos` usando IDs de alumnos existentes (alumno_id entre 1 y 5). Luego verifica con SELECT que los datos est\\xe1n ah\\xed.\",\n        starterSQL: \"-- Primero verifica que pagos existe:\\n-- CREATE TABLE IF NOT EXISTS pagos (id INTEGER PRIMARY KEY AUTOINCREMENT, alumno_id INTEGER NOT NULL, concepto TEXT NOT NULL, monto REAL CHECK(monto>0), fecha TEXT NOT NULL);\\n\\nINSERT INTO pagos (alumno_id, concepto, monto, fecha) VALUES\\n  (1, 'Inscripci\\xf3n semestral', 2500.00, '2026-02-01'),\\n  \",\n        tags: [\n            \"INSERT INTO\",\n            \"DML\",\n            \"datos\",\n            \"VALUES\"\n        ],\n        hints: [\n            {\n                text: \"Puedes insertar m\\xfaltiples filas con VALUES (a),(b),(c)\",\n                xpCost: 0\n            },\n            {\n                text: \"Despu\\xe9s del INSERT, ejecuta: SELECT * FROM pagos;\",\n                xpCost: 5\n            }\n        ],\n        validator: (results)=>{\n            const r = results[0];\n            if (!r) return {\n                passed: false,\n                feedback: \"Ejecuta SELECT * FROM pagos al final.\"\n            };\n            if (r.rows.length < 3) return {\n                passed: false,\n                feedback: `Solo ${r.rows.length} registros. Inserta al menos 3.`\n            };\n            if (!hasColumn(r, \"monto\")) return {\n                passed: false,\n                feedback: \"Verifica que la tabla pagos tiene la columna monto.\"\n            };\n            return {\n                passed: true,\n                feedback: `✅ ${r.rows.length} pagos insertados correctamente.`\n            };\n        }\n    },\n    {\n        id: 10,\n        slug: \"actualizar-datos\",\n        title: \"Actualizar registros\",\n        subtitle: \"DML: UPDATE\",\n        unitId: 3,\n        difficulty: 2,\n        xpReward: 100,\n        estimatedTime: \"10 min\",\n        context: '\\uD83D\\uDDC4️ El Tesorero: \"Los datos cambian. Actualiza el promedio de un alumno espec\\xedfico y verifica el cambio.\"',\n        objective: \"Actualiza el `promedio` del alumno con `id=1` a exactamente **9.5**. Luego verifica con SELECT que el cambio se aplic\\xf3.\",\n        starterSQL: \"-- Actualiza el promedio del alumno id=1\\nUPDATE alumnos\\nSET promedio = \\nWHERE id = 1;\\n\\n-- Verifica el cambio:\\nSELECT id, nombre, promedio FROM alumnos WHERE id = 1;\",\n        tags: [\n            \"UPDATE\",\n            \"SET\",\n            \"WHERE\",\n            \"DML\"\n        ],\n        hints: [\n            {\n                text: \"UPDATE tabla SET columna = valor WHERE condicion;\",\n                xpCost: 0\n            },\n            {\n                text: \"Aseg\\xfarate de incluir el WHERE o actualizar\\xe1s todos los registros\",\n                xpCost: 5\n            }\n        ],\n        validator: (results)=>{\n            const r = results[results.length - 1];\n            if (!r) return {\n                passed: false,\n                feedback: \"Sin resultados. Ejecuta SELECT al final.\"\n            };\n            const promIdx = r.columns.findIndex((c)=>c.toLowerCase() === \"promedio\");\n            if (promIdx < 0) return {\n                passed: false,\n                feedback: \"Incluye columna promedio en el SELECT de verificaci\\xf3n.\"\n            };\n            const val = Number(r.rows[0]?.[promIdx]);\n            if (Math.abs(val - 9.5) > 0.01) return {\n                passed: false,\n                feedback: `El promedio es ${val}, debe ser 9.5.`\n            };\n            return {\n                passed: true,\n                feedback: \"✅ Promedio actualizado correctamente a 9.5.\"\n            };\n        }\n    },\n    {\n        id: 11,\n        slug: \"eliminar-datos\",\n        title: \"Limpiar registros\",\n        subtitle: \"DML: DELETE\",\n        unitId: 3,\n        difficulty: 3,\n        xpReward: 120,\n        estimatedTime: \"12 min\",\n        context: '\\uD83D\\uDDC4️ El Tesorero: \"El DBA tambi\\xe9n debe eliminar datos obsoletos. Pero siempre con cuidado — un DELETE sin WHERE es catastr\\xf3fico.\"',\n        objective: \"Elimina de `bitacora_accesos` todos los registros donde `exitoso = 0` (intentos fallidos). Verifica con SELECT que solo quedan registros exitosos.\",\n        starterSQL: \"-- CUIDADO: siempre usa WHERE en DELETE\\nDELETE FROM bitacora_accesos\\nWHERE exitoso = 0;\\n\\n-- Verifica:\\nSELECT COUNT(*) AS restantes, MIN(exitoso) AS min_exitoso FROM bitacora_accesos;\",\n        tags: [\n            \"DELETE\",\n            \"WHERE\",\n            \"DML\",\n            \"bit\\xe1cora\"\n        ],\n        hints: [\n            {\n                text: \"DELETE FROM tabla WHERE condicion — no olvides el WHERE\",\n                xpCost: 0\n            },\n            {\n                text: \"Verifica con SELECT COUNT(*) que no queden registros con exitoso=0\",\n                xpCost: 5\n            }\n        ],\n        validator: (results)=>{\n            const r = results[results.length - 1];\n            if (!r) return {\n                passed: false,\n                feedback: \"Sin resultados.\"\n            };\n            const minIdx = r.columns.findIndex((c)=>c.toLowerCase().includes(\"min\"));\n            if (minIdx >= 0) {\n                const minVal = Number(r.rows[0]?.[minIdx]);\n                if (minVal === 0) return {\n                    passed: false,\n                    feedback: \"A\\xfan hay registros con exitoso=0. El DELETE no se aplic\\xf3.\"\n                };\n            }\n            return {\n                passed: true,\n                feedback: \"✅ Registros fallidos eliminados correctamente de la bit\\xe1cora.\"\n            };\n        }\n    },\n    // ══ U4: ÍNDICES Y OPTIMIZACIÓN ════════════════════════════════════════════════\n    {\n        id: 12,\n        slug: \"subquery-avg\",\n        title: \"Alumnos sobre el promedio\",\n        subtitle: \"Subconsulta correlacionada\",\n        unitId: 4,\n        difficulty: 3,\n        xpReward: 140,\n        estimatedTime: \"15 min\",\n        context: '\\uD83D\\uDD27 El Mec\\xe1nico: \"Las subconsultas son el sello de un SQL avanzado. Encuentra alumnos que superan el promedio general.\"',\n        objective: \"Muestra nombre, n\\xfamero de control y promedio de los alumnos cuyo `promedio` es **mayor al promedio general** de todos los alumnos activos.\",\n        starterSQL: \"SELECT numero_control, nombre, promedio\\nFROM alumnos\\nWHERE activo = 1\\n  AND promedio > (\\n    -- Subconsulta: calcula el promedio general\\n    \\n  )\\nORDER BY promedio DESC;\",\n        tags: [\n            \"subconsulta\",\n            \"AVG\",\n            \"WHERE subquery\"\n        ],\n        hints: [\n            {\n                text: \"La subconsulta devuelve un escalar: SELECT AVG(promedio) FROM alumnos WHERE activo=1\",\n                xpCost: 0\n            },\n            {\n                text: \"AND promedio > (SELECT AVG(promedio) FROM alumnos WHERE activo=1)\",\n                xpCost: 10\n            }\n        ],\n        validator: (results)=>{\n            const r = results[0];\n            if (!r) return {\n                passed: false,\n                feedback: \"Sin resultados.\"\n            };\n            if (r.rows.length === 0) return {\n                passed: false,\n                feedback: \"Ning\\xfan resultado. \\xbfSe ejecut\\xf3 la subconsulta?\"\n            };\n            if (r.rows.length > 30) return {\n                passed: false,\n                feedback: \"Demasiados resultados. La subconsulta no parece estar filtrando.\"\n            };\n            if (!hasColumn(r, \"promedio\")) return {\n                passed: false,\n                feedback: \"Incluye columna promedio.\"\n            };\n            return {\n                passed: true,\n                feedback: `✅ Subconsulta correcta: ${r.rows.length} alumnos sobre el promedio general.`\n            };\n        }\n    },\n    {\n        id: 13,\n        slug: \"crear-indice\",\n        title: \"Crear un \\xedndice\",\n        subtitle: \"DDL: CREATE INDEX\",\n        unitId: 4,\n        difficulty: 3,\n        xpReward: 150,\n        estimatedTime: \"15 min\",\n        context: '\\uD83D\\uDD27 El Mec\\xe1nico: \"Un \\xedndice compuesto acelera las b\\xfasquedas frecuentes. Crea uno para las consultas de alumnos por carrera y semestre.\"',\n        objective: \"Crea un \\xedndice llamado `idx_carrera_semestre` sobre la tabla `alumnos`, indexando las columnas `carrera` y `semestre`. Luego verifica que aparece en sqlite_master.\",\n        starterSQL: \"-- Crea el \\xedndice compuesto\\nCREATE INDEX IF NOT EXISTS idx_carrera_semestre\\n  ON alumnos (\",\n        tags: [\n            \"CREATE INDEX\",\n            \"DDL\",\n            \"optimizaci\\xf3n\",\n            \"\\xedndice compuesto\"\n        ],\n        hints: [\n            {\n                text: \"CREATE INDEX nombre ON tabla (col1, col2)\",\n                xpCost: 0\n            },\n            {\n                text: \"Despu\\xe9s: SELECT name,tbl_name FROM sqlite_master WHERE type='index'\",\n                xpCost: 5\n            }\n        ],\n        validator: (results)=>{\n            const r = results[0];\n            if (!r) return {\n                passed: false,\n                feedback: \"Sin resultados. Verifica con SELECT sobre sqlite_master.\"\n            };\n            const names = r.rows.map((row)=>String(row[0]).toLowerCase());\n            if (!names.includes(\"idx_carrera_semestre\")) return {\n                passed: false,\n                feedback: \"El \\xedndice idx_carrera_semestre no aparece. \\xbfSe cre\\xf3 correctamente?\"\n            };\n            return {\n                passed: true,\n                feedback: \"✅ \\xcdndice idx_carrera_semestre creado y verificado.\"\n            };\n        }\n    },\n    {\n        id: 14,\n        slug: \"explain-plan\",\n        title: \"Analizar el plan de ejecuci\\xf3n\",\n        subtitle: \"EXPLAIN QUERY PLAN\",\n        unitId: 4,\n        difficulty: 3,\n        xpReward: 160,\n        estimatedTime: \"18 min\",\n        context: '\\uD83D\\uDD27 El Mec\\xe1nico: \"Antes de confiar en un \\xedndice, verifica que el motor lo usa. EXPLAIN revela el plan de ejecuci\\xf3n.\"',\n        objective: \"Ejecuta `EXPLAIN QUERY PLAN` sobre la consulta: `SELECT * FROM alumnos WHERE carrera = 'ISC' AND semestre = 6`. Verifica que el plan menciona el \\xedndice `idx_carrera_semestre`.\",\n        starterSQL: \"-- Primero crea el \\xedndice si no existe:\\nCREATE INDEX IF NOT EXISTS idx_carrera_semestre ON alumnos(carrera, semestre);\\n\\n-- Ahora analiza el plan:\\nEXPLAIN QUERY PLAN\\nSELECT * FROM alumnos WHERE carrera = 'ISC' AND semestre = 6;\",\n        tags: [\n            \"EXPLAIN\",\n            \"plan de ejecuci\\xf3n\",\n            \"\\xedndices\",\n            \"optimizaci\\xf3n\"\n        ],\n        hints: [\n            {\n                text: 'EXPLAIN QUERY PLAN muestra si usa \"USING INDEX\" o \"SCAN\"',\n                xpCost: 0\n            },\n            {\n                text: \"Si dice SCAN TABLE, el \\xedndice no existe o no aplica\",\n                xpCost: 5\n            }\n        ],\n        validator: (results)=>{\n            const r = results[results.length - 1];\n            if (!r) return {\n                passed: false,\n                feedback: \"Ejecuta EXPLAIN QUERY PLAN.\"\n            };\n            const planText = r.rows.map((row)=>String(row[row.length - 1]).toLowerCase()).join(\" \");\n            if (planText.includes(\"scan table alumnos\") && !planText.includes(\"index\")) {\n                return {\n                    passed: false,\n                    feedback: \"El plan hace SCAN sin \\xedndice. \\xbfCreaste idx_carrera_semestre primero?\"\n                };\n            }\n            if (planText.includes(\"idx_carrera_semestre\") || planText.includes(\"using index\")) {\n                return {\n                    passed: true,\n                    feedback: \"✅ El plan usa el \\xedndice idx_carrera_semestre. \\xd3ptimo.\"\n                };\n            }\n            return {\n                passed: true,\n                feedback: \"✅ Plan de ejecuci\\xf3n analizado. Observa si usa SEARCH o SCAN.\"\n            };\n        }\n    },\n    {\n        id: 15,\n        slug: \"cte-reporte\",\n        title: \"CTE: Consultas legibles\",\n        subtitle: \"WITH clause\",\n        unitId: 4,\n        difficulty: 4,\n        xpReward: 170,\n        estimatedTime: \"20 min\",\n        context: '\\uD83D\\uDD27 El Mec\\xe1nico: \"Los CTEs hacen el SQL m\\xe1s legible. Es el est\\xe1ndar en c\\xf3digo de producci\\xf3n.\"',\n        objective: \"Usa un CTE para calcular primero el **promedio por semestre**, y luego en la consulta principal muestra solo los semestres cuyo promedio supera **8.5**.\",\n        starterSQL: \"WITH promedios_semestre AS (\\n  SELECT semestre, AVG(promedio) AS prom_semestre\\n  FROM alumnos\\n  WHERE activo = 1\\n  GROUP BY semestre\\n)\\nSELECT semestre, ROUND(prom_semestre, 2) AS promedio\\nFROM promedios_semestre\\nWHERE prom_semestre > ;\\nORDER BY prom_semestre DESC;\",\n        tags: [\n            \"CTE\",\n            \"WITH\",\n            \"subconsulta nombrada\",\n            \"legibilidad\"\n        ],\n        hints: [\n            {\n                text: \"El CTE se define con WITH nombre AS (SELECT ...) y se usa como tabla\",\n                xpCost: 0\n            },\n            {\n                text: \"HAVING vs WHERE en CTE: en la consulta externa usa WHERE prom_semestre > 8.5\",\n                xpCost: 10\n            }\n        ],\n        validator: (results)=>{\n            const r = results[0];\n            if (!r) return {\n                passed: false,\n                feedback: \"Sin resultados.\"\n            };\n            if (r.rows.length === 0) return {\n                passed: false,\n                feedback: \"Sin filas. Verifica el umbral WHERE prom_semestre > 8.5.\"\n            };\n            const allOver = r.rows.every((row)=>{\n                const idx = r.columns.findIndex((c)=>c.toLowerCase().includes(\"prom\"));\n                return idx >= 0 && Number(row[idx]) > 8.5;\n            });\n            if (!allOver) return {\n                passed: false,\n                feedback: \"Hay semestres con promedio ≤8.5. Revisa el WHERE en la consulta externa.\"\n            };\n            return {\n                passed: true,\n                feedback: `✅ CTE correcto: ${r.rows.length} semestres con promedio > 8.5.`\n            };\n        }\n    },\n    // ══ U5: SEGURIDAD / TRANSACCIONES ════════════════════════════════════════════\n    {\n        id: 16,\n        slug: \"vista-seguridad\",\n        title: \"Vista de datos sensibles\",\n        subtitle: \"CREATE VIEW para acceso limitado\",\n        unitId: 5,\n        difficulty: 3,\n        xpReward: 150,\n        estimatedTime: \"15 min\",\n        context: '\\uD83D\\uDEE1️ El Guardi\\xe1n: \"En seguridad, nunca expones la tabla directamente. Crea una vista que oculte el n\\xfamero de control.\"',\n        objective: \"Crea una vista llamada `v_alumnos_publico` que muestre solo: `nombre`, `apellido_p`, `semestre`, `carrera`, `promedio` — sin exponer `numero_control`. Luego consulta la vista.\",\n        starterSQL: \"-- Crea la vista con columnas seguras\\nCREATE VIEW IF NOT EXISTS v_alumnos_publico AS\\nSELECT nombre, apellido_p, semestre, carrera, promedio\\nFROM alumnos;\\n\\n-- Verifica la vista:\\nSELECT * FROM v_alumnos_publico LIMIT 5;\",\n        tags: [\n            \"CREATE VIEW\",\n            \"seguridad\",\n            \"acceso m\\xednimo\",\n            \"encapsulamiento\"\n        ],\n        hints: [\n            {\n                text: \"CREATE VIEW nombre AS SELECT ...; despu\\xe9s haz SELECT * FROM nombre_vista\",\n                xpCost: 0\n            }\n        ],\n        validator: (results)=>{\n            const r = results[results.length - 1];\n            if (!r) return {\n                passed: false,\n                feedback: \"Sin resultados.\"\n            };\n            if (hasColumn(r, \"numero_control\")) return {\n                passed: false,\n                feedback: \"La vista expone numero_control. Qu\\xedtala de la definici\\xf3n.\"\n            };\n            if (!hasColumn(r, \"nombre\")) return {\n                passed: false,\n                feedback: \"La vista debe incluir columna nombre.\"\n            };\n            if (r.rows.length === 0) return {\n                passed: false,\n                feedback: \"La vista est\\xe1 vac\\xeda. Verifica la consulta interna.\"\n            };\n            return {\n                passed: true,\n                feedback: `✅ Vista v_alumnos_publico creada: oculta numero_control, expone ${r.columns.length} columnas seguras.`\n            };\n        }\n    },\n    {\n        id: 17,\n        slug: \"transaccion-rollback\",\n        title: \"BEGIN → ROLLBACK\",\n        subtitle: \"Control de transacciones\",\n        unitId: 5,\n        difficulty: 4,\n        xpReward: 180,\n        estimatedTime: \"20 min\",\n        context: '\\uD83D\\uDEE1️ El Guardi\\xe1n: \"Toda operaci\\xf3n cr\\xedtica va en una transacci\\xf3n. Si algo falla, el ROLLBACK deshace todo.\"',\n        objective: \"Demuestra el concepto: inicia una transacci\\xf3n, inserta un pago, verifica que existe, luego haz ROLLBACK y verifica que desapareci\\xf3.\",\n        starterSQL: \"-- Paso 1: crea tabla si no existe\\nCREATE TABLE IF NOT EXISTS pagos (id INTEGER PRIMARY KEY AUTOINCREMENT, alumno_id INTEGER, concepto TEXT, monto REAL, fecha TEXT);\\n\\n-- Paso 2: Inicia transacci\\xf3n\\nBEGIN TRANSACTION;\\n  INSERT INTO pagos (alumno_id, concepto, monto, fecha) VALUES (1, 'Prueba ROLLBACK', 100, '2026-01-01');\\n-- Verifica que existe:\\nSELECT COUNT(*) AS en_transaccion FROM pagos WHERE concepto='Prueba ROLLBACK';\\n\\n-- Paso 3: deshaz\\nROLLBACK;\\n\\n-- Verifica que desapareci\\xf3:\\nSELECT COUNT(*) AS tras_rollback FROM pagos WHERE concepto='Prueba ROLLBACK';\",\n        tags: [\n            \"BEGIN\",\n            \"ROLLBACK\",\n            \"transacciones\",\n            \"ACID\"\n        ],\n        hints: [\n            {\n                text: \"BEGIN TRANSACTION; ... ROLLBACK; — el dato desaparece como si nunca hubiera existido\",\n                xpCost: 0\n            }\n        ],\n        validator: (results)=>{\n            const last = results[results.length - 1];\n            if (!last) return {\n                passed: false,\n                feedback: \"Sin resultados.\"\n            };\n            const count = Number(last.rows[0]?.[0]);\n            if (count > 0) return {\n                passed: false,\n                feedback: `Tras el ROLLBACK aún hay ${count} registros. ¿Ejecutaste ROLLBACK?`\n            };\n            if (results.length < 2) return {\n                passed: false,\n                feedback: \"Ejecuta las consultas de verificaci\\xf3n antes y despu\\xe9s del ROLLBACK.\"\n            };\n            return {\n                passed: true,\n                feedback: \"✅ ROLLBACK correcto: el registro desapareci\\xf3 como si nunca existiera. Eso es ACID en acci\\xf3n.\"\n            };\n        }\n    },\n    {\n        id: 18,\n        slug: \"transaccion-commit\",\n        title: \"BEGIN → COMMIT\",\n        subtitle: \"Persistir una transacci\\xf3n\",\n        unitId: 5,\n        difficulty: 3,\n        xpReward: 150,\n        estimatedTime: \"15 min\",\n        context: '\\uD83D\\uDEE1️ El Guardi\\xe1n: \"El COMMIT hace el cambio permanente. Entiende la diferencia con ROLLBACK.\"',\n        objective: \"Inicia una transacci\\xf3n, inserta 2 pagos, haz COMMIT y verifica que persisten con SELECT.\",\n        starterSQL: \"CREATE TABLE IF NOT EXISTS pagos (id INTEGER PRIMARY KEY AUTOINCREMENT, alumno_id INTEGER, concepto TEXT, monto REAL, fecha TEXT);\\n\\nBEGIN TRANSACTION;\\n  INSERT INTO pagos (alumno_id, concepto, monto, fecha) VALUES (1, 'Seminario', 300, '2026-02-15');\\n  INSERT INTO pagos (alumno_id, concepto, monto, fecha) VALUES (2, 'Material', 150, '2026-02-15');\\nCOMMIT;\\n\\nSELECT * FROM pagos;\",\n        tags: [\n            \"COMMIT\",\n            \"transacciones\",\n            \"persistencia\",\n            \"ACID\"\n        ],\n        hints: [\n            {\n                text: \"BEGIN → operaciones → COMMIT: los datos quedan permanentes\",\n                xpCost: 0\n            }\n        ],\n        validator: (results)=>{\n            const r = results[results.length - 1];\n            if (!r) return {\n                passed: false,\n                feedback: \"Sin resultados.\"\n            };\n            if (r.rows.length < 2) return {\n                passed: false,\n                feedback: `Solo ${r.rows.length} registros. El COMMIT debe persistir 2 pagos.`\n            };\n            return {\n                passed: true,\n                feedback: `✅ COMMIT exitoso: ${r.rows.length} pagos persistidos correctamente.`\n            };\n        }\n    },\n    // ══ U6: MONITOREO / ANALYTICS ════════════════════════════════════════════════\n    {\n        id: 19,\n        slug: \"window-ranking\",\n        title: \"Ranking con Window Functions\",\n        subtitle: \"ROW_NUMBER() OVER\",\n        unitId: 6,\n        difficulty: 4,\n        xpReward: 190,\n        estimatedTime: \"20 min\",\n        context: '\\uD83D\\uDD2E El Or\\xe1culo: \"Los dashboards modernos usan window functions. Genera un ranking de alumnos por promedio dentro de cada semestre.\"',\n        objective: \"Muestra: nombre, semestre, promedio y `ranking` (1=mejor) dentro de cada semestre usando `ROW_NUMBER() OVER (PARTITION BY semestre ORDER BY promedio DESC)`. Solo alumnos activos.\",\n        starterSQL: \"SELECT\\n  nombre,\\n  semestre,\\n  promedio,\\n  ROW_NUMBER() OVER (\\n    PARTITION BY semestre\\n    ORDER BY promedio DESC\\n  ) AS ranking\\nFROM alumnos\\nWHERE activo = 1\\nORDER BY semestre, ranking;\",\n        tags: [\n            \"window function\",\n            \"ROW_NUMBER\",\n            \"PARTITION BY\",\n            \"analytics\"\n        ],\n        hints: [\n            {\n                text: \"ROW_NUMBER() OVER (PARTITION BY col ORDER BY col DESC) numera dentro de cada grupo\",\n                xpCost: 0\n            }\n        ],\n        validator: (results)=>{\n            const r = results[0];\n            if (!r) return {\n                passed: false,\n                feedback: \"Sin resultados.\"\n            };\n            if (!hasColumn(r, \"ranking\")) return {\n                passed: false,\n                feedback: \"Incluye columna ranking usando ROW_NUMBER().\"\n            };\n            const rank1Count = r.rows.filter((row)=>{\n                const idx = r.columns.findIndex((c)=>c.toLowerCase() === \"ranking\");\n                return idx >= 0 && Number(row[idx]) === 1;\n            }).length;\n            if (rank1Count < 3) return {\n                passed: false,\n                feedback: `Solo ${rank1Count} rankings con valor 1. ¿Configuraste PARTITION BY semestre?`\n            };\n            return {\n                passed: true,\n                feedback: `✅ Window function correcta: ${rank1Count} semestres con su alumno #1 rankeado.`\n            };\n        }\n    },\n    {\n        id: 20,\n        slug: \"dashboard-metricas\",\n        title: \"Dashboard de m\\xe9tricas\",\n        subtitle: \"Reporte ejecutivo completo\",\n        unitId: 6,\n        difficulty: 4,\n        xpReward: 200,\n        estimatedTime: \"25 min\",\n        context: '\\uD83D\\uDD2E El Or\\xe1culo: \"El reporte ejecutivo consolida todo en una vista. Genera las m\\xe9tricas clave del sistema escolar.\"',\n        objective: \"Crea una consulta que muestre 4 m\\xe9tricas en una sola fila: `total_alumnos`, `alumnos_activos`, `promedio_general` (redondeado a 2 decimales), `total_inscripciones`.\",\n        starterSQL: \"SELECT\\n  COUNT(DISTINCT a.id)       AS total_alumnos,\\n  SUM(CASE WHEN a.activo=1 THEN 1 ELSE 0 END) AS alumnos_activos,\\n  ROUND(AVG(a.promedio), 2)  AS promedio_general,\\n  COUNT(i.id)               AS total_inscripciones\\nFROM alumnos a\\nLEFT JOIN inscripciones i ON i.alumno_id = a.id;\",\n        tags: [\n            \"CASE WHEN\",\n            \"COUNT DISTINCT\",\n            \"LEFT JOIN\",\n            \"dashboard\"\n        ],\n        hints: [\n            {\n                text: \"SUM(CASE WHEN condicion THEN 1 ELSE 0 END) es el equivalente a COUNT IF\",\n                xpCost: 0\n            }\n        ],\n        validator: (results)=>{\n            const r = results[0];\n            if (!r) return {\n                passed: false,\n                feedback: \"Sin resultados.\"\n  